-- 001_init.sql : core schema (PostgreSQL, UUID PKs, audit fields, soft deletes)
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, email TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT UNIQUE NOT NULL);
CREATE TABLE user_roles (user_id UUID REFERENCES users(id) ON DELETE CASCADE, role_id UUID REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(user_id, role_id));
CREATE TABLE sites (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, region TEXT, address TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, email TEXT, phone TEXT, status TEXT DEFAULT 'active', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX idx_customers_org ON customers(org_id);
CREATE TABLE customer_contacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID REFERENCES customers(id) ON DELETE CASCADE, kind TEXT, value TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE service_addresses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID REFERENCES customers(id) ON DELETE CASCADE, label TEXT, address TEXT, lat DOUBLE PRECISION, lng DOUBLE PRECISION, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE bandwidth_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, down_mbps INT NOT NULL, up_mbps INT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE packages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, price_cents BIGINT NOT NULL CHECK (price_cents >= 0), profile_id UUID REFERENCES bandwidth_profiles(id), service_type TEXT DEFAULT 'pppoe', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE subscriptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), customer_id UUID REFERENCES customers(id), package_id UUID REFERENCES packages(id), username TEXT NOT NULL, status TEXT DEFAULT 'pending', device_id UUID, vlan INT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX idx_subs_customer ON subscriptions(customer_id);
CREATE TABLE network_services (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id UUID REFERENCES subscriptions(id) ON DELETE CASCADE, service_type TEXT NOT NULL, external_ref TEXT, status TEXT DEFAULT 'pending', idempotency_key TEXT UNIQUE, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), site_id UUID REFERENCES sites(id), vendor TEXT NOT NULL, family TEXT, model TEXT, firmware TEXT, host TEXT NOT NULL, connection_type TEXT NOT NULL, status TEXT DEFAULT 'unknown', last_success TIMESTAMPTZ, last_error TEXT, latency_ms BIGINT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE device_credentials (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), device_id UUID REFERENCES devices(id) ON DELETE CASCADE, username_enc TEXT NOT NULL, password_enc TEXT NOT NULL, key_version INT DEFAULT 1, rotated_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE device_capabilities (device_id UUID REFERENCES devices(id) ON DELETE CASCADE, capability TEXT NOT NULL, state TEXT NOT NULL, updated_at TIMESTAMPTZ DEFAULT now(), PRIMARY KEY(device_id, capability));
CREATE TABLE connectors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), vendor TEXT NOT NULL, family TEXT NOT NULL, connection_type TEXT NOT NULL, base_url TEXT, status TEXT DEFAULT 'planned', doc_url TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE ip_pools (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, cidr TEXT NOT NULL, version INT DEFAULT 4, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE ip_addresses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pool_id UUID REFERENCES ip_pools(id), address INET NOT NULL, allocated_to UUID, status TEXT DEFAULT 'free');
CREATE TABLE vlans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), site_id UUID REFERENCES sites(id), vlan_id INT NOT NULL, name TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), customer_id UUID REFERENCES customers(id), subscription_id UUID REFERENCES subscriptions(id), subtotal_cents BIGINT DEFAULT 0, discount_cents BIGINT DEFAULT 0, tax_cents BIGINT DEFAULT 0, late_fee_cents BIGINT DEFAULT 0, total_cents BIGINT DEFAULT 0, paid_cents BIGINT DEFAULT 0, status TEXT DEFAULT 'draft', due_at TIMESTAMPTZ NOT NULL, grace_until TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX idx_invoices_status ON invoices(status);
CREATE TABLE invoice_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID REFERENCES invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, qty INT NOT NULL, unit_cents BIGINT NOT NULL, amount_cents BIGINT NOT NULL);
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), invoice_id UUID REFERENCES invoices(id), amount_cents BIGINT NOT NULL, method TEXT NOT NULL, provider TEXT, reference TEXT, status TEXT DEFAULT 'pending', idempotency_key TEXT UNIQUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE payment_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payment_id UUID REFERENCES payments(id) ON DELETE CASCADE, raw JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE radius_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), username TEXT NOT NULL, password_hash TEXT NOT NULL, profile_id UUID REFERENCES bandwidth_profiles(id), expires_at TIMESTAMPTZ, max_sessions INT DEFAULT 1, UNIQUE(org_id, username));
CREATE TABLE radius_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username TEXT NOT NULL, nas_ip TEXT, acct_session_id TEXT UNIQUE, framed_ip INET, started_at TIMESTAMPTZ DEFAULT now(), last_interim TIMESTAMPTZ);
CREATE TABLE radius_accounting (id BIGSERIAL PRIMARY KEY, username TEXT NOT NULL, acct_session_id TEXT NOT NULL, acct_status_type TEXT NOT NULL, input_octets BIGINT DEFAULT 0, output_octets BIGINT DEFAULT 0, recorded_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX idx_acct_session ON radius_accounting(acct_session_id);
CREATE TABLE olt_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), device_id UUID REFERENCES devices(id), vendor TEXT, model TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE onus (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), olt_id UUID REFERENCES olt_devices(id), serial TEXT NOT NULL, status TEXT DEFAULT 'unknown', rx_power FLOAT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE network_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), kind TEXT NOT NULL, payload JSONB, idempotency_key TEXT UNIQUE, status TEXT DEFAULT 'queued', attempts INT DEFAULT 0, max_attempts INT DEFAULT 5, last_error TEXT, run_at TIMESTAMPTZ DEFAULT now(), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE network_job_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), job_id UUID REFERENCES network_jobs(id) ON DELETE CASCADE, attempt INT NOT NULL, result TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE automation_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, conditions JSONB NOT NULL, action TEXT NOT NULL, params JSONB, enabled BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE automation_executions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rule_id UUID REFERENCES automation_rules(id), facts JSONB, fired BOOLEAN, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE alerts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), severity TEXT NOT NULL, title TEXT NOT NULL, body TEXT, status TEXT DEFAULT 'open', created_at TIMESTAMPTZ DEFAULT now(), resolved_at TIMESTAMPTZ);
CREATE TABLE events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), type TEXT NOT NULL, actor TEXT, resource TEXT, resource_id TEXT, payload JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), actor TEXT, action TEXT NOT NULL, resource TEXT, resource_id TEXT, before JSONB, after JSONB, ip TEXT, user_agent TEXT, result TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), channel TEXT NOT NULL, to_addr TEXT NOT NULL, subject TEXT, body TEXT, status TEXT DEFAULT 'queued', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE api_keys (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), name TEXT NOT NULL, key_hash TEXT NOT NULL, scopes TEXT[], revoked BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE webhooks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID REFERENCES organizations(id), url TEXT NOT NULL, secret_enc TEXT, events TEXT[], enabled BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE webhook_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), webhook_id UUID REFERENCES webhooks(id) ON DELETE CASCADE, event_id UUID, status INT, response TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE traffic_samples (id BIGSERIAL PRIMARY KEY, device_id UUID REFERENCES devices(id), target TEXT NOT NULL, rx_bps BIGINT, tx_bps BIGINT, sampled_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE interface_samples (id BIGSERIAL PRIMARY KEY, device_id UUID REFERENCES devices(id), ifname TEXT NOT NULL, rx_bps BIGINT, tx_bps BIGINT, errors BIGINT, sampled_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE system_settings (key TEXT PRIMARY KEY, value JSONB, updated_at TIMESTAMPTZ DEFAULT now());
